const clone=<T,>(x:T):T=>JSON.parse(JSON.stringify(x));
const readLocal=<T,>(key:string,fallback:T):T=>{try{const raw=localStorage.getItem(key);return raw?JSON.parse(raw) as T:fallback}catch{return fallback}};
const readList=<T,>(key:string,fallback:T[]):T[]=>{const value=readLocal<unknown>(key,fallback);return Array.isArray(value)?value as T[]:fallback};
const defaultPrefs:Prefs={theme:'warm',voice:true,reminders:true,privacy:true,dailyHours:2,languages:['JavaScript'],skills:[]};
const normalizePrefs=(value:unknown):Prefs=>{const parsed=value&&typeof value==='object'?value as Partial<Prefs>:{};const theme=themeOptions.some(([v])=>v===parsed.theme)?parsed.theme:'warm';return {...defaultPrefs,...parsed,theme:theme as Theme,languages:Array.isArray(parsed.languages)&&parsed.languages.length?parsed.languages:['JavaScript'],skills:Array.isArray(parsed.skills)?parsed.skills:[]}};
type StudyTask={id:string;title:string;minutes:number;priority:'High'|'Medium'|'Low';due:string;status:'todo'|'done';objective?:string;resourceName?:string;resourceUrl?:string;practice?:string;outcome?:string};
