type QuizQuestion={id:string;prompt:string;options:string[];answer:number;explanation:string};
type SkillAttempt={skill:string;score:number;best:number;latest:number;at:string;source:'sample_questions'};
const sampleQuestionBanks:Record<string,QuizQuestion[]>={
 JavaScript:[['js1','What does a closure let a function retain?',['A reference to its lexical environment','Only its return value','The browser DOM','A compiled CSS rule'],0,'A closure retains access to variables from its lexical environment.'],['js2','Which method creates a new array without mutating the source?',['push()','map()','sort()','splice()'],1,'map returns a new array.'],['js3','What does await do inside an async function?',['Blocks the whole browser','Pauses that async function until the promise settles','Cancels the promise','Converts a promise to a callback'],1,'await pauses the async function, not the entire browser thread.'],['js4','Which value is strictly equal to the string one?',['1','true','null','undefined'],0,'The number 1 is not strictly equal to the string 1; this option is the string.'],['js5','What is a useful reason to use const?',['It prevents object mutation','It prevents reassignment of the binding','It makes code asynchronous','It disables garbage collection'],1,'const prevents reassignment of the binding; object contents can still change.']].map((row:any)=>{const [id,prompt,options,answer,explanation]=row;return {id,prompt,options,answer,explanation}}),
 React:[['r1','Why are keys used when rendering lists?',['To help React track item identity','To style every item','To call an API','To enable CSS modules'],0,'Stable keys help React match list items between renders.'],['r2','What should a controlled input read from?',['A React state value','The URL only','A CSS variable','A server secret'],0,'Controlled inputs use state as their source of truth.'],['r3','Which hook is intended for side effects?',['useMemo','useEffect','useId','useRef'],1,'useEffect is used for synchronising with external systems and side effects.'],['r4','What is a good accessibility practice for a custom button?',['Use a div only','Provide keyboard and focus behaviour','Hide it from screen readers','Disable tab navigation'],1,'Interactive controls need keyboard access and visible focus.'],['r5','Why split a large component?',['To make state and responsibilities easier to reason about','To remove all props','To avoid testing','To guarantee faster APIs'],0,'Smaller responsibilities improve readability and testability.']].map((row:any)=>{const [id,prompt,options,answer,explanation]=row;return {id,prompt,options,answer,explanation}}),
 DSA:[['d1','What is average lookup time in a hash map?',['O(1)','O(log n)','O(n²)','O(n!)'],0,'Average-case lookup is commonly O(1), with caveats about collisions.'],['d2','What does a stack use?',['FIFO','LIFO','Random order','Priority only'],1,'A stack is last-in, first-out.'],['d3','Two pointers are often useful for…',['Sorted arrays and window-like scans','Only recursion','CSS layout','Database backups'],0,'Two pointers can reduce nested scans in ordered data.'],['d4','What does Big O describe?',['Growth of resource use as input grows','Exact runtime on one laptop','A programming language','A test score'],0,'Big O describes asymptotic growth.'],['d5','Which structure is naturally FIFO?',['Queue','Stack','Set','Tree'],0,'A queue is first-in, first-out.']].map((row:any)=>{const [id,prompt,options,answer,explanation]=row;return {id,prompt,options,answer,explanation}})
};
