function Brand(){return <div className="brand"><div className="mark"><svg viewBox="0 0 40 40" aria-hidden="true"><path d="M8 29 28 8l4 4-21 20-3-3Z"/><path d="m26 8 6 0-2 6"/><circle cx="10" cy="30" r="3"/></svg></div><div><b>PATH<span>/</span>PILOT</b><small>career, reverse-engineered</small></div></div>}
function Badge({children,kind='mint'}:{children:React.ReactNode;kind?:string}){return <span className={`badge ${kind}`}>{children}</span>}
function Icon({name}:{name:string}){return <span className="icon" aria-hidden="true">{({home:'⌂',galaxy:'✦',chart:'◒',planner:'◫',mentor:'◉',settings:'⚙',arrow:'→',check:'✓',spark:'✧',target:'◎',clock:'◷',book:'▤'} as Record<string,string>)[name]||'•'}</span>}
function Button({children,onClick,kind='primary',className='',type='button'}:{children:React.ReactNode;onClick?:()=>void;kind?:string;className?:string;type?:'button'|'submit'}){return <button type={type} onClick={onClick} className={`btn ${kind} ${className}`}>{children}</button>}


