function SkillsSelector({skills,setSkills,label='Preferred skills'}:{skills:string[];setSkills:(skills:string[])=>void;label?:string}){const [open,setOpen]=useState(false);const [query,setQuery]=useState('');const [custom,setCustom]=useState('');const add=(skill:string)=>{const v=skill.trim();if(v&&!skills.includes(v))setSkills([...skills,v])};const remove=(skill:string)=>setSkills(skills.filter(x=>x!==skill));const groups=Object.entries(skillGroups).map(([g,items])=>[g,items.filter(x=>!query||x.toLowerCase().includes(query.toLowerCase()))] as const).filter(([,items])=>items.length);return <div className="skills-selector"><span className="selector-label">{label}</span><div className="skill-chips">{skills.map(x=><button type="button" key={x} className="skill-chip" onClick={()=>remove(x)}>{x} ×</button>)}<button type="button" className="skills-trigger" onClick={()=>setOpen(!open)}>{skills.length?'Add skill':'Choose skills'} {open?'⌃':'⌄'}</button></div>{open&&<div className="skills-menu"><input autoFocus value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search skills…"/><div className="skill-groups">{groups.map(([g,items])=><div key={g}><b>{g}</b>{items.map(x=><button type="button" key={x} className={skills.includes(x)?'picked':''} onClick={()=>add(x)}>{skills.includes(x)?'✓':'+'} {x}</button>)}</div>)}</div><div className="custom-skill"><input value={custom} onChange={e=>setCustom(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'){e.preventDefault();add(custom);setCustom('')}}} placeholder="Add custom skill"/><button type="button" onClick={()=>{add(custom);setCustom('')}}>Add</button></div><div className="skills-menu-foot"><span>{skills.length} selected</span>{skills.length>0&&<button type="button" className="text-btn" onClick={()=>setSkills([])}>Clear all</button>}</div></div>}</div>}

